const output = $('summarizer').first().json.output;
const sessionId = $('sub_trigger').first().json.id;
const clips = [];

if (output.technical_ability_clips && output.technical_ability_clips.length) {
  for (const c of output.technical_ability_clips) {
    clips.push({
      session_id: sessionId,
      text: c.quote,
      start_time: c.start_time,
      end_time: c.end_time,
      evidence_field: 'technical_ability'
    });
  }
}

if (output.profile_summary_clips && output.profile_summary_clips.length) {
  for (const c of output.profile_summary_clips) {
    clips.push({
      session_id: sessionId,
      text: c.quote,
      start_time: c.start_time,
      end_time: c.end_time,
      evidence_field: 'profile_summary'
    });
  }
}

if (!clips.length) return [];
return clips.map(c => ({ json: c }));
